// Run from the repository root: bun docs/verification/2026-10-15-req234-c2-fence-preverify/preverify.ts
// Fixture paths come from server.ts / process-fence-plan.ts / engine-config-truth.ts;
// no owner config is read. The profile is generated by the production planner.
import assert from "node:assert/strict"
import { spawnSync } from "node:child_process"
import { existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, statSync, symlinkSync, writeFileSync } from "node:fs"
import { createServer } from "node:net"
import { tmpdir } from "node:os"
import { dirname, join, relative, resolve } from "node:path"
import { planProcessFence } from "../../../packages/ui-mac/src/main/process-fence-plan"
import { SANDBOX_EXEC, trialCompileProfile } from "../../../packages/ui-mac/src/main/process-fence-compile"

const run = realpathSync(mkdtempSync(join(import.meta.dir, "fixture-")))
const home = join(run, "home")
const appState = join(home, "Library/Application Support/alpha-code-state")
const globalRoot = join(appState, "env/prod")
const userData = join(home, "Library/Application Support/ai.opencode.desktop")
const workspace = join(home, "code-puppy")
const proxy = createServer((socket) => socket.end("preverify\n"))
await new Promise<void>((resolve) => proxy.listen(0, "127.0.0.1", resolve))
const address = proxy.address()
assert(address && typeof address !== "string")
const output: { name: string; command: string[]; status: number | null; stdout: string; stderr: string }[] = []
const profiles: Record<string, string> = {}
const temporaryControls: string[] = []
const summary = { passed: false }
const exec = (name: string, command: string[]) => {
  // Do not pass the caller's credentials or app-specific environment into probes.
  const result = spawnSync(command[0], command.slice(1), {
    encoding: "utf8", timeout: 30_000,
    env: { PATH: "/usr/bin:/bin:/usr/sbin:/sbin", HOME: home, TMPDIR: run },
  })
  const row = { name, command, status: result.status, stdout: result.stdout.trim(), stderr: result.stderr.trim() }
  output.push(row)
  console.log(`${name}: rc=${row.status} ${row.stdout || row.stderr}`)
  assert.ifError(result.error)
  return row
}

try {
  ;[globalRoot, userData, workspace].forEach((p) => mkdirSync(p, { recursive: true }))
  const plan = planProcessFence(
    {
      userDataPath: userData,
      sidecarEnv: { HOME: home },
      egressProxyPort: address.port,
      addon: {
        packaged: false,
        resourcesPath: "",
        moduleDir: "/Users/tide/app/alpha-code/packages/ui-mac/out/main",
        exists: existsSync,
      },
    },
    {
      homeDir: () => home,
      alphaGlobalRoot: () => globalRoot,
      appStateRoot: () => appState,
      realpath: realpathSync.native,
      defaultWorkspace: () => workspace,
      readWorkspaces: () => [],
      isDirectory: (p) => existsSync(p) && statSync(p).isDirectory(),
      mkdirp: (p) => void mkdirSync(p, { recursive: true }),
      compile: (profile) => trialCompileProfile(profile, { tmpdir: () => run }),
      log: console.log,
    },
  )
  const config = join(globalRoot, "alpha.jsonc")
  const pluginRoots = [join(home, ".opencode"), join(plan.roots.configHome, "opencode"), join(userData, "alpha-engine-config")]
    .flatMap((p) => [join(p, "plugin"), join(p, "plugins")])
  // Exact two rules from #1530, with ~ / XDG / userData expanded to planner roots.
  const denies = `(deny file-write* (literal "${config}"))\n(deny file-write* ${pluginRoots.map((p) => `(subpath "${p}")`).join(" ")})\n`
  const profile = plan.profile.replace("(deny network*)", `${denies}(deny network*)`)
  assert.equal(profile.replace(denies, ""), plan.profile)
  assert.equal(profile.indexOf(denies), plan.profile.indexOf("(deny network*)"))
  const original = join(run, "original.sb")
  const restricted = join(run, "restricted.sb")
  writeFileSync(original, plan.profile)
  writeFileSync(restricted, profile)
  profiles.original = plan.profile
  profiles.restricted = profile
  const targets = [config, ...pluginRoots.map((p) => join(p, "x.js"))]
  targets.forEach((p) => mkdirSync(join(p, ".."), { recursive: true }))
  targets.forEach((p) => writeFileSync(p, "// preverify sentinel\n"))
  assert.equal(exec("compile-two-denies", [SANDBOX_EXEC, "-f", restricted, "/usr/bin/true"]).status, 0)
  for (const target of targets) {
    assert.equal(exec(`original-echo:${relative(home, target)}`, [SANDBOX_EXEC, "-f", original, "/bin/sh", "-c", 'echo probe >> "$1"', "--", target]).status, 0)
    const before = readFileSync(target)
    const result = exec(`two-denies-echo:${relative(home, target)}`, [SANDBOX_EXEC, "-f", restricted, "/bin/sh", "-c", 'echo probe >> "$1"', "--", target])
    assert.notEqual(result.status, 0, `BLOCKED: appended deny did not protect ${target}`)
    assert.match(result.stderr, /Operation not permitted/)
    assert.deepEqual(readFileSync(target), before)
  }
  for (const target of targets) {
    for (const action of ["append", "create", "truncate", "unlink", "rename"]) {
      for (const [arm, file, expected] of [["original", original, "OK"], ["two-denies", restricted, "EPERM"]]) {
        writeFileSync(target, "sentinel\n")
        const source = join(target === config ? globalRoot : dirname(dirname(target)), "replacement.tmp")
        writeFileSync(source, "replacement\n")
        if (action === "create") rmSync(target)
        const result = exec(`${arm}-${action}:${relative(home, target)}`, [SANDBOX_EXEC, "-f", file, process.execPath, join(import.meta.dir, "fs-probe.mjs"), action, target, source])
        assert.equal(result.status, 0)
        assert.equal(JSON.parse(result.stdout).code, expected, `BLOCKED: ${action} on ${target}`)
        if (expected === "EPERM") {
          assert.equal(JSON.parse(result.stdout).errno, -1)
          if (action === "create") assert(!existsSync(target))
          else assert.equal(readFileSync(target, "utf8"), "sentinel\n")
        }
      }
    }
  }
  // Both absent-directory creation and writing a new plugin file must be forbidden.
  for (const target of pluginRoots) {
    for (const [arm, file, expected] of [["original", original, "OK"], ["two-denies", restricted, "EPERM"]]) {
      rmSync(target, { recursive: true, force: true })
      const result = exec(`${arm}-mkdir:${relative(home, target)}`, [SANDBOX_EXEC, "-f", file, process.execPath, join(import.meta.dir, "fs-probe.mjs"), "mkdir", target])
      assert.equal(result.status, 0)
      assert.equal(JSON.parse(result.stdout).code, expected)
    }
    mkdirSync(target)
    writeFileSync(join(target, "x.js"), "// sentinel\n")
  }
  // Representative writes under every path-based allow rule, plus exact-prefix siblings.
  temporaryControls.push(mkdtempSync("/private/tmp/alpha-1530-"), realpathSync(mkdtempSync(join(tmpdir(), "alpha-1530-"))))
  assert(temporaryControls[1].startsWith("/private/var/folders/"))
  const controls = [
    ["W1", join(workspace, "probe")], ["W2", join(globalRoot, "skills/probe")],
    ["literal-sibling", join(globalRoot, "alpha.jsonc.bak")], ["W3", join(userData, "opencode/locks/probe")],
    ["W4", join(plan.roots.dataHome, "opencode/probe")], ["W5", join(plan.roots.cacheHome, "opencode/probe")],
    ["W6", join(plan.roots.configHome, "opencode/node_modules/probe")], ["W7", join(home, ".npm/probe")],
    ["W8", join(home, ".zsh_history.new")], ["W10", join(home, ".zsh_sessions/probe")],
    ["W11", join(temporaryControls[0], "probe")], ["W12", join(temporaryControls[1], "probe")],
    ["W16", join(home, ".opencode/opencode.jsonc")], ["W17", join(home, "Library/Caches/bun/probe")],
    ["W18", join(home, ".cache/bun/probe")], ["W19", join(home, ".zcompdump-probe")],
    ...[join(home, ".opencode"), join(plan.roots.configHome, "opencode"), join(userData, "alpha-engine-config")]
      .flatMap((p, i) => [[`config-sibling-${i}`, join(p, "opencode.json")], [`plugin-prefix-sibling-${i}`, join(p, "plugins-extra/probe")]]),
  ]
  for (const [name, target] of controls) {
    mkdirSync(dirname(target), { recursive: true })
    for (const [arm, file] of [["original", original], ["two-denies", restricted]]) {
      const result = exec(`${arm}-allow:${name}`, [SANDBOX_EXEC, "-f", file, "/bin/sh", "-c", 'echo control >> "$1"', "--", target])
      assert.equal(result.status, 0)
    }
    assert.equal(readFileSync(target, "utf8"), "control\ncontrol\n")
  }
  for (const [arm, file] of [["original", original], ["two-denies", restricted]]) {
    assert.equal(exec(`${arm}-read-protected`, [SANDBOX_EXEC, "-f", file, "/bin/cat", ...targets]).status, 0)
    assert.equal(exec(`${arm}-allow:W13`, [SANDBOX_EXEC, "-f", file, "/bin/sh", "-c", 'echo null >/dev/null; echo stdout >/dev/stdout; echo stderr >/dev/stderr']).status, 0)
    assert.equal(exec(`${arm}-allow:W14-W15`, [SANDBOX_EXEC, "-f", file, "/usr/bin/script", "-q", "/dev/null", "/bin/sh", "-c", 'echo tty >/dev/tty; echo fd >/dev/fd/1']).status, 0)
    assert.equal(exec(`${arm}-allow:N2-N3-listen`, [SANDBOX_EXEC, "-f", file, process.execPath, "-e", 'const server = require("node:net").createServer(); server.listen(0, "127.0.0.1", () => { console.log("listen OK"); server.close() })']).status, 0)
    assert.equal(exec(`${arm}-allow:N4-connect`, [SANDBOX_EXEC, "-f", file, "/usr/bin/nc", "-z", "-w", "1", "127.0.0.1", String(address.port)]).status, 0)
    const result = exec(`${arm}-outside-denied`, [SANDBOX_EXEC, "-f", file, process.execPath, join(import.meta.dir, "fs-probe.mjs"), "create", join(home, "outside")])
    assert.equal(JSON.parse(result.stdout).code, "EPERM")
  }
  // Same protected targets, but in a real Electron main without sandbox-exec.
  const built = await Bun.build({
    entrypoints: [join(import.meta.dir, "main-probe.ts")], outdir: run, naming: "[name].cjs", target: "node", format: "cjs",
    external: ["electron", "jsonc-parser"],
    banner: 'process.on("uncaughtException", (error) => { console.error(error); require("electron").app.exit(1) })',
  })
  assert(built.success, built.logs.join("\n"))
  mkdirSync(join(run, "node_modules"))
  symlinkSync(realpathSync(resolve(import.meta.dir, "../../../packages/ui-mac/node_modules/jsonc-parser")), join(run, "node_modules/jsonc-parser"))
  // Production alpha-config-injection.ts seed; no user content or credentials.
  writeFileSync(config, JSON.stringify({ $schema: "https://opencode.ai/config.json" }, null, 2))
  const mainInput = join(run, "main-input.json")
  writeFileSync(mainInput, JSON.stringify({ targets, userData, logs: join(userData, "logs"), catalog: resolve(import.meta.dir, "../../../packages/ui-mac/src/renderer/extensions/alpha-catalog.json") }))
  const electron = "/Users/tide/app/alpha-code/node_modules/.bun/electron@42.3.3+759ce506b1ed1a42/node_modules/electron/dist/Electron.app/Contents/MacOS/Electron"
  const main = exec("unfenced-electron-main", [electron, built.outputs[0].path, mainInput])
  assert.equal(main.status, 0)
  assert.equal(JSON.parse(main.stdout).processType, "browser")
  summary.passed = true
  console.log("PASS: seven protected targets; six absent plugin directories; allow controls; unfenced Electron main config apply/restore")
} finally {
  writeFileSync(join(import.meta.dir, "results.json"), JSON.stringify({ summary, run, profiles, output }, null, 2) + "\n")
  proxy.close()
  rmSync(run, { recursive: true, force: true })
  temporaryControls.forEach((p) => rmSync(p, { recursive: true, force: true }))
}
